## Review: Matrix Multiplication

 $$ \begin{aligned}Q&=\begin{bmatrix}q_{11}&q_{12}&\cdots&q_{1d_{k}}\\q_{21}&q_{22}&\cdots&q_{2d_{k}}\\\vdots&\vdots&\ddots&\vdots\\q_{L1}&q_{L2}&\cdots&q_{Ld_{k}}\end{bmatrix},\quad K^{\top}=\begin{bmatrix}k_{11}&k_{21}&\cdots&k_{L1}\\k_{12}&k_{22}&\cdots&k_{L2}\\\vdots&\vdots&\ddots&\vdots\\k_{1d_{k}}&k_{2d_{k}}&\cdots&k_{Ld_{k}}\end{bmatrix}\in\mathbb{R}^{d_{k}\times L}\\S&=Q K^{\top}=\begin{bmatrix}\sum_{r=1}^{d_{k}}q_{1r}k_{1r}&\sum_{r=1}^{d_{k}}q_{1r}k_{2r}&\cdots&\sum_{r=1}^{d_{k}}q_{1r}k_{Lr}\\\sum_{r=1}^{d_{k}}q_{2r}k_{1r}&\sum_{r=1}^{d_{k}}q_{2r}k_{2r}&\cdots&\sum_{r=1}^{d_{k}}q_{2r}k_{Lr}\\\vdots&\vdots&\ddots&\vdots\\\sum_{r=1}^{d_{k}}q_{Lr}k_{1r}&\sum_{r=1}^{d_{k}}q_{Lr}k_{2r}&\cdots&\sum_{r=1}^{d_{k}}q_{Lr}k_{Lr}\end{bmatrix}\in\mathbb{R}^{L\times L}\\S_{ij}&=Q_{i,:}K_{j,:}^{T}=[q_{i1}\quad q_{i2}\quad\cdots\quad q_{id_{k}}]\begin{bmatrix}k_{j1}\\k_{j2}\\\vdots\\k_{jd_{k}}\end{bmatrix}=\sum_{r=1}^{d_{k}}q_{ir}k_{jr}\in\mathbb{R}\\ Matrix~Multiplication\end{aligned} $$ 

 $$ (i,j)\mapsto S_{i j}=\sum_{r=1}^{d_{k}}Q_{i r}K_{j r} $$ 

## ○○○○

// Naive CUDA GEMM: S = QK^T
// Each CUDA thread computes one S[row][col]

__global__ void gemm(float *Q, float *K, float *S, int L, int dk)
{
    // Which output element does this thread compute?
    int col = blockIdx.x * blockDim.x + threadIdx.x;
    int row = blockIdx.y * blockDim.y + threadIdx.y;

// Check whether (row, col) is valid
if (row < L && col < L)
{
    float sum = 0.0f;

    // Row "row" of Q × row "col" of K
    // (= column "col" of K^T)
    for (int k = 0; k < dk; k++)
    {
        sum += Q[row * dk + k]
        * K[col * dk + k];
    }

    // Store one output element S[row][col]
    S[row * L + col] = sum;
}

