## Shared-Memory Tiling GEMM

#define TILE_SIZE 16

// Tiled GEMM: C = A * B
// Each CUDA thread computes one output element C[row][col]
__global__ void tiledGEMM(float *A, float *B, float *C, int
0)

// Shared-memory tiles
__shared__ float As[TILE_SIZE][TILE_SIZE];
__shared__ float Bs[TILE_SIZE][TILE_SIZE];

// Thread position inside the block
int tx = threadIdx.x;
int ty = threadIdx.y;

// Output element computed by this thread
int col = blockIdx.x * TILE_SIZE + tx;
int row = blockIdx.y * TILE_SIZE + ty;

float sum = 0.0f;

// Move along the K dimension tile by tile
for (int t = 0; t < (N + TILE_SIZE - 1) / TILE_SIZE; t++)
{
    //------------------------
//1. Global Memory -> Shared Memory
//------------------------
// Each thread loads one element of A
int A_col = t * TILE_SIZE + tx;

if (row < N && A_col < N)
    As[ty][tx] = A[row * N + A_col];
else
    As[ty][tx] = 0.0f;

// Each thread loads one element of B
int B_row = t * TILE_SIZE + ty;

if (B_row < N && col < N)
    Bs[ty][tx] = B[B_row * N + col];
else
    Bs[ty][tx] = 0.0f;

// Wait until the whole tile has been loaded
__syncthreads();

//------------------------
//2. Compute using data in Shared Memory
//------------------------
for (int k = 0; k < TILE_SIZE; k++)
{
    sum += As[ty][k] * Bs[k][tx];
}

// Make sure all threads finish using this tile
// before loading the next tile
__syncthreads();

//------------------------
//3. Write the final result to Global Memory
//------------------------
if (row < N && col < N)
{
    C[row * N + col] = sum;
}

