## Achieve Naive Stable Softmax

__global__ void stableSoftmax(const float* x, float* y, int B, int N)
{
    // One block processes one Softmax vector
    int row = blockIdx.x;

    if (row >= B) return;

    const float* input = x + row * N;
    float* output = y + row * N;

    // Shared by all threads in this block
    __shared__ float m;
    __shared__ float d;

    // Pass 1 and Pass 2 are still sequential
    if (threadIdx.x == 0) {
        m = -INFINITY;
        d = 0.0f;

        // Pass 1: find maximum
        for (int i = 0; i < N; i++) {
            m = fmaxf(m, input[j]);
        }

        // Pass 2: compute normalizer
        for (int j = 0; j < N; j++) {
            d += expf(input[j] - m);
        }
    }

    // Wait until m and d are ready
    __syncthreads();

    // Pass 3: compute final Softmax values in parallel
    for (int j = threadIdx.x; j < N; j += blockDim.x) {
        output[j] = expf(input[j] - m) / d;
    }
}

 $$ \begin{array}{l l}{\operatorname{D e p e n d e n c y}}&{\left\{\begin{array}{l l}&{m=m a x\underset{i\in A}{x_{i}}}\\ &{d=\displaystyle\sum_{j=1}^{V}e x p\left(x_{j}-m\right)}\end{array}\right.}\\ \end{array} $$ 

 $$ y_{i}=\frac{exp(x_{i})}{\sum_{j=1}^{V}exp\left(x_{j-m}-m\right)} $$

