## Achieve Naive Online Softmax

__global__ void onlineSoftmax(const float* x, float* y, int B, int N)
{
    // One block processes one Softmax vector
    int row = blockIdx.x;

    if (row >= B) return;

    const float* input = x + row * N;
    float* output = y + row * N;

    // Online Softmax state
    __shared__ float m;
    __shared__ float d;

    // Pass 1: update running maximum m and running normalizer d together
    if (threadIdx.x == 0) {
        m = -INFINITY;
        d = 0.0f;

        for (int j = 0; j < N; j++) {
            float m_new = fmaxf(m, input[j]);

            d = d * expf(m - m_new) + expf(input[j] - m_new);

            m = m_new;
        }
    }

    // Wait until m and d are ready
    __syncthreads();

    // Pass 2: compute final Softmax values in parallel
    for (int j = threadIdx.x; j < N; j += blockDim.x) {
        output[j] = expf(input[j] - m) / d;
    }
}

 $ m_j = \max(m_{j-1}, x_j) $

 $ d_j = \sum_{i=1}^{j-1} e^{x_i - m_{j-1} + m_{j-1} - m_j} + e^{x_j - m_j} $

